/// Deterministic randomness for content generation.
///
/// `dart:math` `Random(seed)` makes no promise to stay the same across SDK
/// versions, and content keys depend on the generated bytes, so the campaign
/// generator uses its own generator (mulberry32) and string hash (FNV-1a with
/// a murmur3 finaliser). Both use only 32-bit arithmetic, so the same seed
/// gives the same levels everywhere.
library;

int _imul(int a, int b) {
  final ah = (a >> 16) & 0xFFFF, al = a & 0xFFFF;
  final bh = (b >> 16) & 0xFFFF, bl = b & 0xFFFF;
  return (al * bl + (((ah * bl + al * bh) & 0xFFFF) << 16)) & 0xFFFFFFFF;
}

int _fmix(int h) {
  h &= 0xFFFFFFFF;
  h ^= h >> 16;
  h = _imul(h, 0x85EBCA6B);
  h ^= h >> 13;
  h = _imul(h, 0xC2B2AE35);
  h ^= h >> 16;
  return h;
}

/// A well-mixed unsigned 32-bit hash of [parts], joined by `|`.
int stableHash(List<Object> parts) {
  var h = 0x811C9DC5;
  for (final unit in parts.join('|').codeUnits) {
    h ^= unit;
    h = _imul(h, 0x01000193);
  }
  return _fmix(h);
}

/// mulberry32: small, fast and good enough for shuffles and weighted picks.
class SeededRandom {
  SeededRandom(int seed) : _state = seed & 0xFFFFFFFF;

  /// A generator seeded from [parts] via [stableHash].
  SeededRandom.of(List<Object> parts) : _state = stableHash(parts);

  int _state;

  int nextUint32() {
    _state = (_state + 0x6D2B79F5) & 0xFFFFFFFF;
    var t = _state;
    t = _imul(t ^ (t >> 15), t | 1);
    t ^= (t + _imul(t ^ (t >> 7), t | 61)) & 0xFFFFFFFF;
    return (t ^ (t >> 14)) & 0xFFFFFFFF;
  }

  /// Uniform in `[0, max)`.
  int nextInt(int max) {
    if (max <= 0) throw ArgumentError.value(max, 'max', 'must be positive');
    // Rejection sampling keeps the result unbiased.
    final limit = 0x100000000 - (0x100000000 % max);
    while (true) {
      final value = nextUint32();
      if (value < limit) return value % max;
    }
  }

  /// Uniform in `[0, 1)`.
  double nextDouble() => nextUint32() / 4294967296.0;

  bool chance(double probability) => nextDouble() < probability;

  T pick<T>(List<T> items) => items[nextInt(items.length)];

  void shuffle<T>(List<T> items) {
    for (var i = items.length - 1; i > 0; i--) {
      final j = nextInt(i + 1);
      final tmp = items[i];
      items[i] = items[j];
      items[j] = tmp;
    }
  }
}
